before:
async function requirePrepared(
  tx: SourceMainResourceTransaction,
  request: Request,
  signal?: AbortSignal,
) {
  current(request, signal);
  if (prepared.get(tx) !== requestText(request))
    fail(
      "Prepare resource predicate tables BEFORE any reservation/resource/claim row lock.",
    );
  // Reacquire actual locks; a WeakMap alone cannot prove that this transaction remains open.
  await prepareCurrentActorPredicateTablesWithin(tx, request.tenantId);
  current(request, signal);
}
async function actorWithin(
  tx: SourceMainResourceTransaction,
  request: Request,
  model: OriginalSelectedAgentModel,
  sessionId: string,
  expected?: ActorPin,
  signal?: AbortSignal,
): Promise<ActorPin> {
  await requirePrepared(tx, request, signal);
  const view = readSelectedAgentModel(model);
  if (
    view.tenantId !== request.tenantId ||
    view.agentId !== request.input.executorAgentId
  )
    fail("The original SDK model belongs to another executor.");
